"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { 
  LayoutDashboard, Inbox, Newspaper, Calendar, 
  Users, CreditCard, QrCode, FileText, 
  Wallet, Package, Settings, LogOut, ChevronRight 
} from "lucide-react";

const menuItems = [
  {
    category: "UTAMA",
    items: [
      { name: "Dashboard", href: "/admin", icon: LayoutDashboard },
      { name: "Inbox Aspirasi", href: "/admin/aspirasi", icon: Inbox },
    ]
  },
  {
    category: "KONTEN & PROYEK",
    items: [
      { name: "Kelola Berita", href: "/admin/berita", icon: Newspaper },
      { name: "Program Kerja", href: "/admin/proker", icon: Calendar },
    ]
  },
  {
    category: "SDM & ABSENSI",
    items: [
      { name: "Data Pengurus", href: "/admin/pengurus", icon: Users },
      { name: "ID Card Studio", href: "/admin/idcard", icon: CreditCard },
      { name: "Scan Absensi", href: "/admin/absensi", icon: QrCode }, // <-- NEXT FEATURE
    ]
  },
  {
    category: "ADMINISTRASI",
    items: [
      { name: "Buat Surat", href: "/admin/surat", icon: FileText }, // <-- PHASE 3
      { name: "Kas & Anggaran", href: "/admin/kas", icon: Wallet }, // <-- PHASE 3
      { name: "Inventaris", href: "/admin/inventaris", icon: Package }, // <-- PHASE 3
    ]
  },
];

export default function Sidebar() {
  const pathname = usePathname();

  return (
    <aside className="w-64 h-screen bg-white dark:bg-[#0f172a] border-r border-slate-200 dark:border-white/5 flex flex-col fixed left-0 top-0 z-50 overflow-y-auto">
      
      {/* BRAND */}
      <div className="p-6 flex items-center gap-3">
        <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-500/30">
           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6">
              <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 01.75.75c0 5.056-2.383 9.555-6.084 12.436-3.118 2.424-7.146 3.814-11.416 3.814a.75.75 0 010-1.5c4.27 0 8.298-1.39 11.416-3.814a.75.75 0 011.06 1.06c-3.12 2.425-7.148 3.815-11.416 3.815a.75.75 0 01-.75-.75v-1.5c0-.414.336-.75.75-.75.414 0 .75.336.75.75v.75c4.27 0 8.298-1.39 11.416-3.814a.75.75 0 01.53-.22.75.75 0 01.53.22c3.118 2.424 7.146 3.814 11.416 3.814a.75.75 0 010 1.5c-4.27 0-8.298 1.39-11.416 3.814a.75.75 0 01-1.06-1.06c3.12-2.425 7.148-3.815 11.416-3.815a.75.75 0 01.75.75v1.5c0 .414-.336.75-.75.75-.414 0-.75-.336-.75-.75v-.75C7.5 22.5 1.5 16.5 1.5 10.5c0-4.142 3.358-7.5 7.5-7.5.414 0 .75.336.75.75s-.336.75-.75.75c-3.314 0-6 2.686-6 6 0 2.703 1.83 4.975 4.315 5.784z" clipRule="evenodd" />
           </svg>
        </div>
        <span className="text-xl font-black text-slate-800 dark:text-white tracking-tight">
          ORBIT<span className="text-blue-600">ADM</span>
        </span>
      </div>

      {/* MENU LIST */}
      <nav className="flex-1 px-4 space-y-6">
        {menuItems.map((group, index) => (
          <div key={index}>
            <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-3 px-3">
              {group.category}
            </p>
            <div className="space-y-1">
              {group.items.map((item) => {
                const isActive = pathname === item.href;
                return (
                  <Link 
                    key={item.href} 
                    href={item.href}
                    className={`flex items-center justify-between px-3 py-2.5 rounded-xl text-sm font-bold transition-all duration-200 group
                      ${isActive 
                        ? "bg-blue-600 text-white shadow-lg shadow-blue-500/30" 
                        : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-white/5 hover:text-blue-600 dark:hover:text-white"
                      }
                    `}
                  >
                    <div className="flex items-center gap-3">
                      <item.icon size={18} className={isActive ? "text-white" : "text-slate-400 group-hover:text-blue-600 dark:group-hover:text-white transition-colors"} />
                      <span>{item.name}</span>
                    </div>
                    {isActive && <ChevronRight size={14} className="text-white/50" />}
                  </Link>
                )
              })}
            </div>
          </div>
        ))}
      </nav>

      {/* FOOTER */}
      <div className="p-4 border-t border-slate-200 dark:border-white/5">
         <button className="flex items-center gap-3 px-3 py-2.5 w-full rounded-xl text-sm font-bold text-slate-500 dark:text-slate-400 hover:bg-red-50 dark:hover:bg-red-900/10 hover:text-red-600 transition-colors">
            <Settings size={18} />
            <span>Pengaturan</span>
         </button>
         <button className="flex items-center gap-3 px-3 py-2.5 w-full rounded-xl text-sm font-bold text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors mt-1">
            <LogOut size={18} />
            <span>Keluar Sistem</span>
         </button>
      </div>

    </aside>
  );
}